    if expected.is_null() {
        assert!(actual.is_none(), "{label}: expected None, got {actual:?}");
        return;
    }
    let actual =
        actual.unwrap_or_else(|| panic!("{label}: expected Some(contactsMetrics), got None"));
    // Hypot-cascaded (summed `measureCanonicalGridBoundaryContact.lengthMm`/
    // `.normalizedUnits`) -- bounded tolerance, see `assert_f64_close`.
    assert_f64_close(
        actual.shared_boundary_length_mm,
        parse_f64_bits(expected["sharedBoundaryLengthMm"].as_str().unwrap()),
        &format!("{label}.sharedBoundaryLengthMm"),
    );
