fn decode_polygon_with_bounds(value: &Value) -> IrregularPolygonWithBounds {
    let points = decode_points(value);
    let bounds = bounds_of(&points);
    IrregularPolygonWithBounds {
        polygon: IrregularPolygon::new(points),
        bounds,
    }
}

