#[test]
fn convex_pair_vectors_match_ts_production_oracle() {
    let file = load_vectors();
    let convex_pair_vectors = file["convexPairVectors"]
        .as_array()
        .expect("convexPairVectors array present");
    assert!(
        !convex_pair_vectors.is_empty(),
        "convexPairVectors must be non-empty"
    );

    for vector in convex_pair_vectors {
        let case_label = vector["caseLabel"].as_str().expect("caseLabel present");
        let first = decode_polygon_with_bounds(&vector["first"]);
        let second = decode_polygon_with_bounds(&vector["second"]);

        let segments = shared_convex_polygon_boundary_segments(&first, &second)
            .unwrap_or_else(|| panic!("{case_label}: expected Some(segments), got None"));
        let expected_segments = vector["segments"]
            .as_array()
            .expect("segments array present");
        assert_eq!(
            segments.len(),
            expected_segments.len(),
            "{case_label}: segments length mismatch"
        );
        for (index, (actual_segment, expected_segment)) in
            segments.iter().zip(expected_segments.iter()).enumerate()
        {
            let segment_label = format!("{case_label}.segments[{index}]");
            assert_f64_bits_eq(
                actual_segment.first_edge_index,
                parse_f64_bits(expected_segment["firstEdgeIndex"].as_str().unwrap()),
                &format!("{segment_label}.firstEdgeIndex"),
            );
            assert_f64_bits_eq(
                actual_segment.second_edge_index,
                parse_f64_bits(expected_segment["secondEdgeIndex"].as_str().unwrap()),
                &format!("{segment_label}.secondEdgeIndex"),
            );
            assert_f64_bits_eq(
                actual_segment.start.x,
                parse_f64_bits(expected_segment["start"]["x"].as_str().unwrap()),
                &format!("{segment_label}.start.x"),
            );
            assert_f64_bits_eq(
                actual_segment.start.y,
                parse_f64_bits(expected_segment["start"]["y"].as_str().unwrap()),
                &format!("{segment_label}.start.y"),
            );
            assert_f64_bits_eq(
                actual_segment.end.x,
                parse_f64_bits(expected_segment["end"]["x"].as_str().unwrap()),
                &format!("{segment_label}.end.x"),
            );
            assert_f64_bits_eq(
                actual_segment.end.y,
                parse_f64_bits(expected_segment["end"]["y"].as_str().unwrap()),
                &format!("{segment_label}.end.y"),
            );
            // Hypot-cascaded -- bounded tolerance, see `assert_f64_close`.
            assert_f64_close(
                actual_segment.length_mm,
                parse_f64_bits(expected_segment["lengthMm"].as_str().unwrap()),
                &format!("{segment_label}.lengthMm"),
            );
        }

        let contact = measure_shared_convex_polygon_boundary_contact(&first, &second);
        assert_convex_contact_eq(contact, &vector["contact"], case_label);
    }
}

#[test]
fn vector_file_header_records_generating_commit_and_meaningful_coverage() {
    let file = load_vectors();
    let generating_commit = file["generatingCommit"]
        .as_str()
        .expect("generatingCommit present");
    assert!(!generating_commit.is_empty());
    let total = file["totalVectorCount"]
        .as_u64()
        .expect("totalVectorCount present");
    assert!(
        total >= 600,
        "expected >= 600 canonical-layout vectors, got {total}"
    );
    let layout_count = file["layoutVectors"].as_array().unwrap().len() as u64;
    let grid_pair_count = file["gridPairVectors"].as_array().unwrap().len() as u64;
    let convex_pair_count = file["convexPairVectors"].as_array().unwrap().len() as u64;
    assert_eq!(
        total,
        layout_count + grid_pair_count + convex_pair_count,
        "totalVectorCount header must match the sum of the three category arrays"
    );
}
